(function ($) {
    $.fn.typed = function (options) {
        const settings = $.extend({
            strings: [''],
            typeSpeed: 80,
            backSpeed: 40,
            startDelay: 400,
            backDelay: 1000,
            loop: true,
            showCursor: true,
            cursorChar: '|'
        }, options);

        return this.each(function () {
            const $element = $(this);
            let currentStringIndex = 0;
            let currentCharIndex = 0;
            let isDeleting = false;
            let timer;

            function buildCursor() {
                if (!settings.showCursor) {
                    $element.next('.typed-cursor').remove();
                    return;
                }

                if ($element.next('.typed-cursor').length === 0) {
                    $('<span class="typed-cursor">').text(settings.cursorChar).insertAfter($element);
                }
            }
            function updateText() {
                const currentString = settings.strings[currentStringIndex % settings.strings.length];

                if (!isDeleting) {
                    $element.text(currentString.slice(0, currentCharIndex + 1));
                    currentCharIndex += 1;

                    if (currentCharIndex >= currentString.length) {
                        clearTimeout(timer);
                        timer = setTimeout(function () {
                            isDeleting = true;
                            updateText();
                        }, settings.backDelay);
                        return;
                    }

                    timer = setTimeout(updateText, settings.typeSpeed);
                    return;
                }

                $element.text(currentString.slice(0, currentCharIndex - 1));
                currentCharIndex -= 1;

                if (currentCharIndex <= 0) {
                    isDeleting = false;
                    currentStringIndex += 1;

                    if (!settings.loop && currentStringIndex >= settings.strings.length) {
                        return;
                    }

                    timer = setTimeout(updateText, settings.startDelay);
                    return;
                }

                timer = setTimeout(updateText, settings.backSpeed);
            }

            buildCursor();
            timer = setTimeout(updateText, settings.startDelay);
        });
    };
})(jQuery);